/**
 * /roster-construction — the gated Roster Construction V1 page and panel,
 * rendered from the backend's golden fixtures (generated by the real module):
 * golden-best-ball-v1.json (team 1 of a 6-team best-ball league) and
 * golden-managed-v1.json (team 2 of a 4-team manual-lineup league).
 *
 * Pins: nothing but "not available" while the gate is closed (flag
 * `roster_construction` off -> 503 feature_disabled, or no route -> 404); the
 * team list comes from the backend's overview and no team is guessed; the
 * production table and the dynasty-value table are separate, each rank with
 * its own denominator; missing values render as stated absences, never 0; the
 * three start concepts are labelled apart with denominators and the
 * hypothetical assumptions; diagnoses show evidence and an explicit NO ACTION;
 * a manual-lineup league is labelled hypothetical optimal with submitted
 * points kept separate; a late answer for another team never renders.
 * Display only.
 */
import fs from "node:fs";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { fireEvent, render, screen, waitFor, within } from "@testing-library/react";

vi.mock("@/components/useLeague", () => ({
  useLeague: () => ({
    leagues: [{ key: "dynasty_main", displayName: "Risk It" }],
    selectedLeagueKey: "dynasty_main",
    setLeague: vi.fn(),
    loading: false,
  }),
}));

import RosterConstructionPage from "@/app/roster-construction/page";
import RosterConstructionPanel from "@/components/roster-construction/RosterConstructionPanel";

const load = (name) =>
  JSON.parse(
    fs.readFileSync(
      path.resolve(__dirname, `../fixtures/roster-construction/${name}.json`),
      "utf-8",
    ),
  );
const BEST_BALL = load("golden-best-ball-v1"); // team 1, 6 teams
const MANAGED = load("golden-managed-v1"); // team 2, 4 teams

function overviewOf(fx) {
  return {
    schemaVersion: fx.schemaVersion,
    leagueKey: fx.leagueKey,
    season: fx.season,
    rules: fx.rules,
    teams: fx.teams,
  };
}

/** The body row carrying this position's badge (exact text match). */
function rowFor(table, position) {
  return within(table)
    .getAllByRole("row")
    .find((r) => within(r).queryAllByText(position, { exact: true }).length > 0);
}

function clone(o) {
  return JSON.parse(JSON.stringify(o));
}

function jsonResponse(status, body) {
  return Promise.resolve({
    ok: status >= 200 && status < 300,
    status,
    json: () => Promise.resolve(body),
  });
}

/** Route the two request shapes: no rosterId = overview/gate, with = team. */
function installFetch({ fixture = BEST_BALL, team, gate } = {}) {
  const calls = [];
  global.fetch = vi.fn((url) => {
    const u = new URL(String(url), "http://x");
    calls.push(u);
    if (gate) return jsonResponse(gate.status, gate.body);
    if (!u.searchParams.get("rosterId")) return jsonResponse(200, overviewOf(fixture));
    return typeof team === "function" ? team(u) : jsonResponse(200, team || fixture);
  });
  return calls;
}

beforeEach(() => {
  vi.restoreAllMocks();
});
afterEach(() => {
  delete global.fetch;
});

describe("gate", () => {
  it("shows only 'not available' when the flag is off", async () => {
    installFetch({
      gate: { status: 503, body: { error: "feature_disabled", flag: "roster_construction" } },
    });
    render(<RosterConstructionPage />);
    await screen.findByTestId("roster-construction-unavailable");
    expect(screen.queryByRole("heading", { name: "Roster Construction" })).toBeNull();
    expect(screen.queryByLabelText("Team")).toBeNull();
  });

  it("shows only 'not available' when the route is not registered", async () => {
    installFetch({ gate: { status: 404, body: {} } });
    render(<RosterConstructionPage />);
    await screen.findByTestId("roster-construction-unavailable");
  });

  it("fills the team selector from the overview and guesses no team", async () => {
    const calls = installFetch();
    render(<RosterConstructionPage />);
    const select = await screen.findByLabelText("Team");
    expect(select.value).toBe("");
    expect(within(select).getAllByRole("option")).toHaveLength(BEST_BALL.teams.length + 1);
    expect(within(select).getByRole("option", { name: "Team 3" })).toBeTruthy();
    expect(await screen.findByRole("heading", { name: "Pick a team" })).toBeTruthy();
    // Only the team-less probe has been sent.
    expect(calls.every((u) => !u.searchParams.get("rosterId"))).toBe(true);
    expect(calls[0].searchParams.get("leagueKey")).toBe("dynasty_main");
  });

  it("states a not-ready backend instead of 'not available'", async () => {
    installFetch({
      gate: { status: 503, body: { error: "data_not_ready", reason: "contract_not_loaded" } },
    });
    render(<RosterConstructionPage />);
    expect(await screen.findByText(/not ready yet/)).toBeTruthy();
    expect(screen.queryByTestId("roster-construction-unavailable")).toBeNull();
  });

  it("requests the picked team and renders its payload", async () => {
    const calls = installFetch();
    render(<RosterConstructionPage />);
    const select = await screen.findByLabelText("Team");
    fireEvent.change(select, { target: { value: "1" } });
    await screen.findByTestId("roster-construction-panel");
    await screen.findByTestId("rc-summary");
    const teamCall = calls.find((u) => u.searchParams.get("rosterId") === "1");
    expect(teamCall.searchParams.get("leagueKey")).toBe("dynasty_main");
  });
});

function renderPanel(fixture, rosterId, props = {}) {
  installFetch({ fixture, team: props.team });
  return render(
    <RosterConstructionPanel leagueKey={fixture.leagueKey} rosterId={String(rosterId)} {...props.panel} />,
  );
}

describe("panel — best-ball golden fixture", () => {
  it("keeps production and value as separate tables, each rank beside its own denominator", async () => {
    renderPanel(BEST_BALL, 1);
    const prod = await screen.findByRole("table", { name: /optimal starter points by position/ });
    const value = screen.getByRole("table", { name: /Dynasty value held at each position/ });
    expect(prod).not.toBe(value);
    // TE: production 6 of 6, dynasty value 1 of 6 (the same denominator here by
    // construction of the fixture; K shows the denominators can differ: 5 of 5).
    expect(rowFor(prod, "TE").textContent).toContain("6 of 6");
    expect(rowFor(prod, "TE").textContent).not.toContain("1 of 6");
    expect(rowFor(value, "TE").textContent).toContain("1 of 6");
    expect(rowFor(prod, "QB").textContent).toContain("1 of 6");
    expect(rowFor(value, "K").textContent).toContain("5 of 5");
    expect(screen.getByText("Two independent measures")).toBeTruthy();
  });

  it("shows the production columns the directive lists", async () => {
    renderPanel(BEST_BALL, 1);
    const prod = await screen.findByRole("table", { name: /optimal starter points by position/ });
    const headers = within(prod).getAllByRole("columnheader").map((h) => h.textContent);
    for (const h of ["Optimal starter pts", "Rank", "Percentile", "League avg", "League median", "Players", "Top contributors", "Weekly"]) {
      expect(headers.some((t) => t.includes(h)), h).toBe(true);
    }
    // QB: 624.0 points, rank 1 of 6, 100th percentile, league mean 302.1 / median 245.2.
    const qb = rowFor(prod, "QB").textContent;
    expect(qb).toContain("624.0");
    expect(qb).toContain("100th");
    expect(qb).toContain("302.1");
    expect(qb).toContain("245.2");
    // Top contributors resolve through the player list (the payload sends ids).
    expect(qb).toContain("t1-qb1");
  });

  it("does not show submitted points or the hypothetical banner for best ball", async () => {
    renderPanel(BEST_BALL, 1);
    await screen.findByTestId("rc-summary");
    expect(screen.queryByText("Hypothetical optimal lineups")).toBeNull();
    expect(screen.queryByRole("columnheader", { name: /Submitted pts/ })).toBeNull();
  });

  it("renders missing values as stated absences, never 0", async () => {
    const fx = clone(BEST_BALL);
    const k = fx.positions.find((p) => p.position === "K");
    Object.assign(k.value, { total: null, rank: null, percentile: null, pricedCount: 0, unpricedCount: 1, unpricedIds: ["t1-k1"], top1Share: null });
    renderPanel(fx, 1, { team: fx });
    const value = await screen.findByRole("table", { name: /Dynasty value held at each position/ });
    const cells = within(rowFor(value, "K")).getAllByRole("cell");
    expect(cells[1].textContent).toBe("Unpriced");
    expect(cells[2].textContent).toBe("Unranked");
  });

  it("states unavailable dynasty value instead of an empty or zero table", async () => {
    const fx = clone(BEST_BALL);
    fx.valueBlock = { available: false, reason: "contract_not_loaded", asOf: null };
    renderPanel(fx, 1, { team: fx });
    expect(await screen.findByText("Dynasty value unavailable")).toBeTruthy();
    expect(screen.queryByRole("table", { name: /Dynasty value held at each position/ })).toBeNull();
    expect(screen.getByRole("table", { name: /optimal starter points by position/ })).toBeTruthy();
  });

  it("pairs production and value in the mismatch table with no trade implication", async () => {
    renderPanel(BEST_BALL, 1);
    const mm = await screen.findByRole("table", { name: /Production rank and dynasty value rank side by side/ });
    const te = rowFor(mm, "TE").textContent;
    expect(te).toContain("6 of 6");
    expect(te).toContain("1 of 6");
    expect(screen.getByText(/not a trade signal/)).toBeTruthy();
  });

  it("separates the three start concepts with denominators and the backend's assumptions", async () => {
    renderPanel(BEST_BALL, 1);
    const players = await screen.findByRole("table", { name: /Per-player starts/ });
    fireEvent.click(rowFor(players, "t1-te3"));
    const detail = await screen.findByTestId("rc-player-detail");
    expect(within(detail).getByText("Actual optimized starts while owned")).toBeTruthy();
    expect(within(detail).getByText("Hypothetical optimal starts")).toBeTruthy();
    expect(within(detail).getByText("League-relative startability")).toBeTruthy();
    // t1-te3: 0 of 8 starts, 0 of 8 hypothetical, 1 of 8 league-startable weeks.
    expect(detail.textContent).toContain("0 of 8");
    expect(detail.textContent).toContain("1 of 8");
    expect(detail.textContent).toContain("Wk 1–8");
    expect(detail.textContent).toContain("Assumption: Uses realized points (ex post)");
    expect(detail.textContent).toContain("No roster cap");
    expect(detail.textContent).toContain("free agents are not in the pool");
    // The hypothetical's own state is stated: no later week of data was used to dress it up.
    expect(detail.textContent).toContain("Low contribution");
  });

  it("states tags, currency and injury on a held-but-idle asset", async () => {
    renderPanel(BEST_BALL, 1);
    const players = await screen.findByRole("table", { name: /Per-player starts/ });
    fireEvent.click(rowFor(players, "t1-te9"));
    const detail = await screen.findByTestId("rc-player-detail");
    expect(detail.textContent).toContain("Injured");
    expect(detail.textContent).toContain("Developmental");
    expect(detail.textContent).toContain("On this team's current roster.");
  });

  it("filters players by position", async () => {
    renderPanel(BEST_BALL, 1);
    const players = await screen.findByRole("table", { name: /Per-player starts/ });
    expect(within(players).getByText("t1-qb1")).toBeTruthy();
    fireEvent.change(screen.getByLabelText("Position"), { target: { value: "TE" } });
    const filtered = screen.getByRole("table", { name: /Per-player starts/ });
    expect(within(filtered).queryByText("t1-qb1")).toBeNull();
    expect(within(filtered).getByText("t1-te9")).toBeTruthy();
  });

  it("shows diagnoses with evidence, an explicit NO ACTION, REVIEW and not-evaluated reasons", async () => {
    renderPanel(BEST_BALL, 1);
    const box = await screen.findByTestId("rc-diagnoses");
    const items = within(box).getAllByTestId("rc-diagnosis");
    const d1 = items.find((e) => e.dataset.rule === "RC-D1" && /No action/.test(e.textContent));
    expect(d1.textContent).toContain("6 of 6");
    expect(d1.textContent).toContain("1 of 6");
    expect(d1.textContent).toContain("injured; developmental");
    expect(d1.textContent).toContain("t1-te9");
    expect(d1.textContent).toContain("needs no action");
    const d2 = items.find((e) => e.dataset.rule === "RC-D2" && /Review/.test(e.textContent));
    expect(d2.textContent).toContain("0.5035");
    const overall = screen.getByTestId("rc-overall").textContent;
    expect(overall).toContain("Overall: Review");
    expect(overall).toContain("Rules checked: RC-D1, RC-D2, RC-D3, RC-D4, RC-D6");
    expect(overall).toContain("RC-D5");
    const d5 = screen.getAllByTestId("rc-diagnosis").find((e) => e.dataset.rule === "RC-D5");
    expect(d5.textContent).toContain("Not evaluated:");
    expect(d5.textContent).toContain("not a pass");
  });

  it("says NO ACTION when nothing fired", async () => {
    const quiet = clone(BEST_BALL);
    quiet.diagnoses = quiet.diagnoses.map((d) =>
      d.status === "fired" ? { ...d, status: "not_fired", verdict: null } : d,
    );
    quiet.overall = { ...quiet.overall, verdict: "NO_ACTION", reviewCount: 0 };
    renderPanel(quiet, 1, { team: quiet });
    expect(await screen.findByText("No rule fired for this team. Nothing here calls for a change.")).toBeTruthy();
    expect(screen.getByTestId("rc-overall").textContent).toContain("Overall: No action");
  });

  it("lists exclusions, parity and the assumptions in the method notes", async () => {
    const fx = clone(BEST_BALL);
    fx.coverage.weeksExcluded = [{ week: 18, reason: "not_final" }];
    fx.team.excludedWeeks = [{ rosterId: 1, week: 3, reason: "host_score_mismatch" }];
    renderPanel(fx, 1, { team: fx });
    await screen.findByTestId("rc-summary");
    const ex = screen.getByTestId("rc-exclusions").textContent;
    expect(ex).toContain("week 18: not final");
    expect(ex).toContain("host score mismatch");
    expect(screen.getByTestId("rc-parity").textContent).toContain("host score reproduced 8 weeks");
    expect(screen.getByText(/value ranks cover the CURRENT rosters/)).toBeTruthy();
    expect(screen.getByText(/not calibrated/)).toBeTruthy();
  });
});

describe("panel — manual-lineup (managed) golden fixture", () => {
  it("labels the league hypothetical optimal and keeps submitted points apart", async () => {
    renderPanel(MANAGED, 2);
    expect(await screen.findByText("Hypothetical optimal lineups")).toBeTruthy();
    expect(screen.getByText(/not the lineups that were submitted/)).toBeTruthy();
    expect(screen.getByTestId("rc-summary").textContent).toContain("8 weeks with an observed submitted lineup");
    const prod = screen.getByRole("table", { name: /hypothetical optimal starter points by position/ });
    const headers = within(prod).getAllByRole("columnheader").map((h) => h.textContent);
    expect(headers.some((t) => t.includes("Hypothetical optimal pts"))).toBe(true);
    expect(headers.some((t) => t.includes("Submitted pts"))).toBe(true);
    // QB: hypothetical optimal 267.5 beside observed submitted 246.7, as separate cells.
    const cells = within(rowFor(prod, "QB")).getAllByRole("cell").map((c) => c.textContent);
    expect(cells).toContain("267.5");
    expect(cells).toContain("246.7");
    expect(cells.indexOf("267.5")).not.toBe(cells.indexOf("246.7"));
  });

  it("renders the 4-team denominators and an unknown lineup marginal as unknown", async () => {
    renderPanel(MANAGED, 2);
    const prod = await screen.findByRole("table", { name: /optimal starter points by position/ });
    expect(rowFor(prod, "QB").textContent).toContain("2 of 4");
    const players = screen.getByRole("table", { name: /Per-player starts/ });
    fireEvent.click(rowFor(players, "t2-db1"));
    const detail = await screen.findByTestId("rc-player-detail");
    expect(detail.textContent).toContain("Unknown");
    expect(detail.textContent).toContain("best-ball leagues");
  });

  it("states posture as unavailable with its reason, not as a label", async () => {
    renderPanel(MANAGED, 2);
    await screen.findByTestId("rc-summary");
    expect(screen.getByText(/Competitive posture:/).textContent).toContain("unavailable");
    expect(screen.getByText(/Competitive posture:/).textContent).toContain("current season, not a past one");
  });

  it("does not claim the contender rule passed when it was not evaluated", async () => {
    renderPanel(MANAGED, 2);
    const d3 = (await screen.findAllByTestId("rc-diagnosis")).find((e) => e.dataset.rule === "RC-D3");
    expect(d3.textContent).toContain("Not evaluated:");
    expect(d3.textContent).toContain("not a pass");
  });
});

describe("panel — failures and guards", () => {
  it("states a backend failure instead of rendering numbers", async () => {
    installFetch({ team: () => jsonResponse(404, { error: "unknown_team" }) });
    render(<RosterConstructionPanel leagueKey="dynasty_main" rosterId="99" />);
    expect(await screen.findByText(/not in this league/)).toBeTruthy();
    expect(screen.queryByTestId("rc-summary")).toBeNull();
  });

  it("never renders a late answer for another team", async () => {
    const other = clone(BEST_BALL);
    other.team = { ...other.team, rosterId: 9, label: "Someone Else" };
    installFetch({ team: other });
    render(<RosterConstructionPanel leagueKey="dynasty_main" rosterId="1" />);
    await waitFor(() => expect(global.fetch).toHaveBeenCalled());
    await new Promise((r) => setTimeout(r, 20));
    expect(screen.queryByText("Someone Else")).toBeNull();
    expect(screen.queryByTestId("rc-summary")).toBeNull();
  });

  it("asks for a team when none is chosen and sends no request", () => {
    installFetch();
    render(<RosterConstructionPanel leagueKey="dynasty_main" rosterId="" />);
    expect(screen.getByRole("heading", { name: "Pick a team" })).toBeTruthy();
    expect(global.fetch).not.toHaveBeenCalled();
  });
});
